<div class="card"><h2>Project settings</h2><form data-api="project-settings"><input type="hidden" name="website_id" value="<?=$wid?>"><div class="form-grid"><?php field('name','Website name','text',$w['name']);field('country','Country','text',$w['country']);field('language','Language','text',$w['language']);field('timezone','Timezone','text',$w['timezone']);select_field('search_engine','Search engine',['google'=>'Google','bing'=>'Bing'],$w['search_engine']);foreach(['client_name'=>'Client name','client_email'=>'Client email'] as $k=>$v)field($k,$v,$k==='client_email'?'email':'text',value('SELECT value FROM website_settings WHERE website_id=? AND name=?',[$wid,$k])?:'',false);?></div><label class="check"><input type="checkbox" name="monthly_report" <?=value("SELECT value FROM website_settings WHERE website_id=? AND name='monthly_report'",[$wid])?'checked':''?>> Generate a report each month</label><button class="button">Save project settings</button></form></div>
